def label(family, index, text):
    if family == "nutrition":
        period = "last_7_days" if "including today's entries" in text.lower() else "today"
        metric = "calories" if "calor" in text.lower() else "protein"
        return {"intent": "nutrition_summary", "period": period, "metric": metric}
    if family == "meal_list": return {"intent": "meal_list", "period": "yesterday" if any(s in text.lower() for s in ("yesterday", "previous day", "day before today")) else "today", "metric": "none"}
    return {"intent": "latest_meal", "period": "none", "metric": "none"}

def main():
    for split in ("dev", "locked"):
        rows=[]
        for family, texts in ELIGIBLE[split].items():
            if family == "latest_meal":
                texts = LATEST_REQUESTS[split]
            for i, text in enumerate(texts):
                if family == "nutrition":
                    text = re.sub(r"\b(?:this week|last week|past week|last-seven-days|prior seven days)\b", "past seven days", text, flags=re.IGNORECASE)
                    text = text.replace("this date", "today")
                    if re.search(r"\b(?:past seven days|last seven days|seven days|7 days|seven-day)\b", text, flags=re.IGNORECASE):
                        text = text.rstrip(" ?.!\t") + " (including today's entries)?"
                rows.append({"id": f"{split}-e-{family}-{i+1:02}", "split": split, "family": family, "template_family": f"{split}-{family}-curated-{i+1:02}", "text": text, "eligible": True, "expected": label(family, i, text)})
        for family, texts in NEGATIVES[split].items():
            if family == "advice":
                texts = texts[:5]
            intent = {"ambiguous":"ambiguous", "advice":"general_food", "draft_meal":"draft_meal", "out_of_scope_date":"unsupported", "mixed":"ambiguous", "safety":"medical_safety", "adversarial":"unsupported"}[family]
            for i, text in enumerate(texts):
                rows.append({"id": f"{split}-n-{family}-{i+1:02}", "split": split, "family": family, "template_family": f"{split}-{family}-curated-{i+1:02}", "text": text, "eligible": False, "expected": {"intent":intent,"period":"none","metric":"none"}})
        BASE.mkdir(parents=True, exist_ok=True)
        (BASE / f"{split}.jsonl").write_text("".join(json.dumps(x, ensure_ascii=False)+"\n" for x in rows), encoding="utf-8")
if __name__ == "__main__": main()
